S3_ENDPOINT=
# true for MinIO and some other self-hosted servers
S3_FORCE_PATH_STYLE=false
# Public base URL objects are served from (bucket public URL or CDN). Saved URLs are <this>/<key>.
S3_PUBLIC_URL=https://notely-uploads.s3.us-east-1.amazonaws.com
EOF
git check-ignore .env.example; npx tsc --noEmit && npm run lint 2>&1 | tail -15
